/** index.mjs 의 타입 선언 — 소비 프로젝트의 eslint.config 와 카탈로그 테스트가 읽는다. */
import type { ESLint, Linter, Rule } from "eslint"

export declare const rules: Record<string, Rule.RuleModule>

export declare const configs: {
  /** 전 규칙을 error 로 켜고, 토큰 정의 파일에서만 색 규칙을 끈 기본 설정. */
  recommended: Linter.Config[]
}

export { RULE_META } from "./meta.mjs"

declare const plugin: ESLint.Plugin & {
  rules: Record<string, Rule.RuleModule>
  configs: typeof configs
}

export default plugin

/**
 * eslint-plugin-doksam-ui — ui.doksam.com 표준의 불변(invariant) 조항 중
 * 정적으로 판정 가능한 것을 소비 프로젝트의 IDE·CI 에서 강제한다(이슈 #40).
 *
 * npm 레지스트리가 아니라 카탈로그의 shadcn 레지스트리로 배포한다 —
 * `npx shadcn add https://ui.doksam.com/r/eslint-plugin.json` 이 이 폴더를 그대로
 * 복사한다. 소비 프로젝트는 표준 자산을 이미 그 경로로 받고 있으므로 새 배포
 * 채널(npm 접근·사내 미러)을 전제하지 않는다 — 폐쇄망 전제와 같은 전제다.
 *
 * 런타임 의존성이 없다. ESLint 는 peer 로 전제하고, 이 파일들은 평문 ESM(.mjs)
 * 이라 빌드 단계도 없다.
 *
 * 사용 (eslint.config.mjs):
 *
 *   import doksam from "./tools/eslint-doksam/index.mjs"
 *   export default [ ...doksam.configs.recommended ]
 *
 * 규칙이 어느 조항에서 나왔는지는 meta.mjs 가 들고 있고, 규칙 원문과의 정합은
 * 카탈로그의 tools/eslint-doksam/coverage.test.ts 가 잠근다.
 */
import { RULE_META } from "./meta.mjs"
import noEmojiIcon from "./rules/no-emoji-icon.mjs"
import noExternalUrl from "./rules/no-external-url.mjs"
import noHardcodedColor from "./rules/no-hardcoded-color.mjs"
import noNestedUiDir from "./rules/no-nested-ui-dir.mjs"
import requireRouteBoundaries from "./rules/require-route-boundaries.mjs"

export const rules = {
  "no-hardcoded-color": noHardcodedColor,
  "no-emoji-icon": noEmojiIcon,
  "no-external-url": noExternalUrl,
  "no-nested-ui-dir": noNestedUiDir,
  "require-route-boundaries": requireRouteBoundaries,
}

const plugin = {
  meta: { name: "doksam-ui", version: "0.1.0" },
  rules,
}

/** 전 규칙을 error 로 켠 기본 설정. 불변 조항이므로 warn 이 아니다. */
const allErrors = Object.fromEntries(Object.keys(rules).map((name) => [`doksam-ui/${name}`, "error"]))

/** 전 규칙을 끈 설정 — 플러그인 자기 소스처럼 규칙이 적용될 자리가 아닌 곳에 쓴다. */
const allOff = Object.fromEntries(Object.keys(rules).map((name) => [`doksam-ui/${name}`, "off"]))

/**
 * 토큰을 정의하는 자리에서는 색 리터럴이 곧 데이터다 — 그 자리에서만 끈다.
 * 규칙 원문의 "themes/<name>.ts 를 추가한다" 가 가리키는 자리와 같다.
 */
const TOKEN_DEFINITION_FILES = [
  "themes/**",
  "**/themes/**",
  "**/*.config.{js,cjs,mjs,ts,mts}",
  // 시맨틱 토큰의 원천값을 적는 자리 — 여기서의 색 리터럴이 곧 토큰이다.
  "**/*-tokens.{ts,mts}",
  "**/tokens/**",
  "**/profile-css.ts",
]

/**
 * 색을 **데이터로 다루는** 파일 — 색 리터럴이 디자인 결정이 아니라 입력값이다.
 *
 * 테스트와 fixture 는 위반 사례 자체를 적어야 하고, 색을 고르거나 변환하는
 * 컴포넌트에서 팔레트는 사용자가 고를 후보지 화면의 시맨틱이 아니다.
 * 카탈로그 자신에게 돌려 실측했을 때 이 두 부류가 오탐의 대부분이었다.
 */
const COLOR_AS_DATA_FILES = [
  "**/color-picker*.{ts,tsx}",
  "**/*color-picker*.{ts,tsx}",
]

/**
 * 테스트와 fixture — 위반 사례 자체를 값으로 적어야 하는 자리다.
 *
 * 색뿐 아니라 외부 URL 도 마찬가지다(폐쇄망 검사를 검사하는 테스트는 외부 URL
 * 문자열을 입력으로 갖는다). 그래서 색만이 아니라 두 규칙을 함께 끈다.
 */
const TEST_FILES = ["**/*.test.{ts,tsx,mts}", "**/*.spec.{ts,tsx,mts}", "**/__fixtures__/**", "**/e2e/**"]

export const configs = {
  recommended: [
    {
      name: "doksam-ui/recommended",
      plugins: { "doksam-ui": plugin },
      rules: allErrors,
    },
    {
      name: "doksam-ui/token-definitions",
      files: TOKEN_DEFINITION_FILES,
      rules: { "doksam-ui/no-hardcoded-color": "off" },
    },
    {
      name: "doksam-ui/color-as-data",
      files: COLOR_AS_DATA_FILES,
      rules: { "doksam-ui/no-hardcoded-color": "off" },
    },
    {
      name: "doksam-ui/tests",
      files: TEST_FILES,
      rules: {
        "doksam-ui/no-hardcoded-color": "off",
        "doksam-ui/no-external-url": "off",
      },
    },
    {
      // 이 플러그인 자신의 소스에는 규칙이 잡아야 할 문자열이 예시로 들어 있다
      // (meta.mjs 의 요약문, no-external-url.mjs 의 remotePatterns 감지 등).
      name: "doksam-ui/self",
      files: ["**/eslint-doksam/**"],
      rules: allOff,
    },
  ],
}

plugin.configs = configs

export { RULE_META }
export default plugin

/** meta.mjs 의 타입 선언 — 카탈로그의 TypeScript 쪽(규칙 표 페이지·정합 테스트)이 읽는다. */

export interface RuleMetaEntry {
  /** 이 규칙이 나온 규칙 원문(lib/rules-markdown.ts)의 절 제목. */
  section: string
  /** 규칙이 무엇을 막는지 한 줄. */
  summary: string
}

export declare const RULE_META: Record<string, RuleMetaEntry>

export type CoverageStatus = "rules" | "delegated" | "judgment" | "catalog-gate" | "aggregate"

export declare const COVERAGE_STATUSES: CoverageStatus[]

export interface CoverageEntry {
  status: CoverageStatus
  /** status 가 "rules" 일 때 그 절을 막는 규칙 이름들. */
  rules?: string[]
  /** 기계로 판정하지 않는 이유, 또는 판정 범위의 한계. */
  note?: string
}

export declare const COVERAGE: Record<string, CoverageEntry>

/**
 * 규칙 메타데이터 — 린트 규칙과 규칙 원문(lib/rules-markdown.ts)을 잇는 유일한 지점.
 *
 * 각 규칙은 자기가 어느 절에서 나왔는지를 `section` 으로 선언하고, 그 문자열은
 * `RULES_SECTIONS` 의 제목과 **글자 단위로 같아야** 한다. `COVERAGE` 는 반대 방향을
 * 잠근다 — 불변(invariant) 절 하나하나가 "어떤 규칙이 막는지" 또는 "왜 기계로
 * 판정하지 않는지" 중 하나를 반드시 갖는다. 둘의 정합은
 * `tools/eslint-doksam/coverage.test.ts` 가 강제하므로, 원문에 불변 절을 추가하면
 * 여기를 갱신하기 전까지 카탈로그 테스트가 깨진다.
 *
 * 이 파일은 순수 데이터다 — ESLint 도, node:fs 도 import 하지 않는다. 카탈로그의
 * /rules/lint 페이지가 이 파일 하나만 읽어 규칙 표를 그린다.
 */

/** 규칙 이름 → 출처 절과 한 줄 요약. */
export const RULE_META = {
  "no-hardcoded-color": {
    section: "컬러 · 토큰",
    summary:
      "hex·rgb()·oklch() 등 색 리터럴과 Tailwind 팔레트 클래스(text-red-500)를 막는다. 색은 시맨틱 토큰(bg-background, text-destructive, text-chart-1)으로만 쓴다.",
  },
  "no-emoji-icon": {
    section: "아이콘",
    summary:
      "JSX 본문·속성·문자열의 그림 이모지를 막는다. 아이콘은 Phosphor(@phosphor-icons/react)를 쓰고, 서버 컴포넌트에서는 /dist/ssr 경로로 import 한다.",
  },
  "no-external-url": {
    section: "폐쇄망 대응",
    summary:
      "외부 http(s) URL 리터럴과 next.config 의 images.remotePatterns 를 막는다. 폰트·아이콘·이미지는 전부 self-host 한다.",
  },
  "no-nested-ui-dir": {
    section: "컴포넌트",
    summary:
      "components/ui/ 안에 하위 폴더(components/ui/customs/ 등)를 만들어 커스텀을 끼워 넣는 것을 막는다. 커스텀은 components/ 또는 components/patterns/ 에서 조합한다.",
  },
  "require-route-boundaries": {
    section: "페이지 · 라우팅",
    summary:
      "app 라우터의 page 파일에 loading·error 경계가 없으면 보고한다. 상위 세그먼트가 이미 제공하면 통과한다(Next 의 실제 적용 범위와 같게 판정).",
  },
}

/**
 * 기계 판정 상태.
 * - `rules` — 이 플러그인의 규칙이 막는다.
 * - `delegated` — 표준 도구가 이미 막는다. 어느 도구인지 적는다.
 * - `judgment` — 사람·AI 의 판단이 필요해 정적으로 판정할 수 없다.
 * - `catalog-gate` — 소비 프로젝트가 아니라 카탈로그 레포의 테스트가 막는 절이다.
 * - `aggregate` — 다른 절의 요약이라 자체 검사가 없다.
 */
export const COVERAGE_STATUSES = ["rules", "delegated", "judgment", "catalog-gate", "aggregate"]

/**
 * 불변 절 → 무엇이 그 절을 막는가.
 *
 * 키는 `RULES_SECTIONS` 의 제목과 같아야 하고, 불변 절이 빠지거나 남으면 테스트가 깨진다.
 * "아직 안 만들었다" 를 조용히 넘기지 않기 위한 장치다 — 기계로 못 잡는 절도
 * 못 잡는다고 명시적으로 적는다.
 */
export const COVERAGE = {
  "디자인 브리프 (생성 전 필수)": {
    status: "judgment",
    note: "DESIGN.md 의 존재는 볼 수 있으나 원형·성격·배제 목록이 실제로 결정을 잘라내는지는 내용 판정이라 정적으로 볼 수 없다. 배제 목록이 '어차피 안 쓸 것' 인지 여부가 이 절의 핵심인데 그 판정이 곧 사람·AI 의 일이다.",
  },
  "수렴 안티패턴": {
    status: "judgment",
    note: "'근거 없이 채택하지 않는다' 가 조항의 형태다 — 같은 코드가 브리프에 따라 위반이기도 아니기도 하다. 린트가 판정하면 전부 오탐이 된다.",
  },
  "컬러 · 토큰": { status: "rules", rules: ["no-hardcoded-color"] },
  컴포넌트: {
    status: "rules",
    rules: ["no-nested-ui-dir"],
    note: "'components/ui/ 를 손으로 고치지 않는다' 의 전면 판정은 상류 원문과의 대조가 필요해 외부 조회 없이는 소비 프로젝트에서 할 수 없다 — 폐쇄망 전제와 충돌하므로 카탈로그의 pnpm check:shadcn 에 남긴다. 정적으로 확정 가능한 조항(하위 폴더 끼워 넣기)만 규칙으로 배포한다.",
  },
  아이콘: { status: "rules", rules: ["no-emoji-icon"] },
  "페이지 · 라우팅": { status: "rules", rules: ["require-route-boundaries"] },
  접근성: {
    status: "delegated",
    note: "eslint-plugin-jsx-a11y 가 이미 막는다(eslint-config-next 의 core-web-vitals 에 포함). 명도대비·'색만으로 전달하지 않는다' 는 렌더 결과를 봐야 하므로 정적 린트의 대상이 아니다.",
  },
  "폐쇄망 대응": { status: "rules", rules: ["no-external-url"] },
  TypeScript: {
    status: "delegated",
    note: "@typescript-eslint/no-explicit-any 와 tsconfig 의 strict 가 막는다. 같은 것을 두 번 구현하지 않는다.",
  },
  "의존성 규율": {
    status: "judgment",
    note: "유지보수 상태·라이선스·번들 비용 판정이라 정적 규칙이 아니다. 판정 근거를 PR 에 남기는 것이 이 절의 절차다.",
  },
  "AI로 설치하기 (shadcn 커스텀 레지스트리)": {
    status: "catalog-gate",
    note: "registryDependencies 의 bare 이름·버전 범위 누락은 카탈로그의 scripts/registry/ui-items.test.ts·closure.test.ts 가 막는다. 소비 프로젝트의 소스에는 판정할 대상이 없다.",
  },
  "표준 준수 체크리스트": {
    status: "aggregate",
    note: "다른 절의 요약이다 — 각 항목은 해당 절의 판정을 따른다.",
  },
}

import { RULE_META } from "../meta.mjs"

/**
 * 이모지를 아이콘 대용으로 쓰는 것을 막는다 — 규칙 원문 "아이콘" 절의 마지막 조항.
 *
 * "이모지로 렌더되는 글자" 만 본다. `\p{Extended_Pictographic}` 하나로 잡으면
 * 화살표(↔)·삼각형(▶)·체크(✔) 같은 **글자 표현이 기본인** 기호까지 걸린다 —
 * 그중 상당수는 본문 안의 문장부호라 아이콘 대용이 아니다(카탈로그 자신에게
 * 돌려 실측했다). 그래서 두 가지만 본다.
 *
 *  1. `Emoji_Presentation=Yes` — 기본 표현이 이모지인 글자 (✅ 🚀 📊)
 *  2. 그림 문자 + 변이 선택자 U+FE0F — 이모지로 렌더해 달라고 명시한 글자 (⚠️)
 *
 * 한글·한자·문장부호는 애초에 걸리지 않으므로 `grep '[^\x00-\x7F]'` 식 스캔의
 * 오탐(한국어 본문 전체)도 없다. 주석은 보지 않는다 — 렌더되지 않는 글이다.
 */

const EMOJI_SOURCE = "(?:\\p{Emoji_Presentation}|\\p{Extended_Pictographic}\\uFE0F)"
const EMOJI = new RegExp(EMOJI_SOURCE, "u")
const EMOJI_ALL = new RegExp(EMOJI_SOURCE, "gu")

function pictographs(text) {
  return [...text.matchAll(EMOJI_ALL)].map((match) => match[0])
}

/** @type {import("eslint").Rule.RuleModule} */
export default {
  meta: {
    type: "problem",
    docs: {
      description: RULE_META["no-emoji-icon"].summary,
      section: RULE_META["no-emoji-icon"].section,
      url: "https://ui.doksam.com/rules/lint",
    },
    schema: [],
    messages: {
      emojiIcon:
        "이모지 '{{value}}' 를 아이콘 대용으로 쓰지 않는다 — Phosphor(@phosphor-icons/react, 서버 컴포넌트는 /dist/ssr)를 쓴다. doksam-ui 규칙 [invariant] '아이콘' (https://ui.doksam.com/rules)",
    },
  },

  create(context) {
    const report = (node, text) => {
      if (typeof text !== "string" || !EMOJI.test(text)) return
      for (const value of pictographs(text)) {
        context.report({ node, messageId: "emojiIcon", data: { value } })
      }
    }

    return {
      JSXText(node) {
        report(node, node.value)
      },
      Literal(node) {
        if (typeof node.value === "string") report(node, node.value)
      },
      TemplateElement(node) {
        report(node, node.value.cooked ?? node.value.raw)
      },
    }
  },
}

import { RULE_META } from "../meta.mjs"

/**
 * 외부 리소스를 **불러오는** 자리를 막는다 — 규칙 원문 "폐쇄망 대응" 절.
 *
 * 조항이 금지하는 것은 "빌드·런타임의 외부 CDN·외부 URL fetch" 이지 URL 을 글자로
 * 적는 것이 아니다. 문자열에 `https://` 가 있다고 전부 잡으면 문서 링크·스키마
 * URL·사용자가 누르는 바깥 링크까지 걸려 오탐이 쏟아지고, 오탐이 쏟아지면 사람은
 * 규칙을 끈다(카탈로그 자신에게 돌려 실측한 결과 84건 중 대부분이 그런 것이었다).
 * 그래서 **리소스를 적재하는 위치**만 본다.
 *
 *  - `src`/`srcSet`/`poster`, `<link href>` 등 브라우저가 받으러 가는 속성
 *  - fetch·axios·new Worker/WebSocket/EventSource/URL 등 런타임 요청
 *  - CSS 의 `url(https://...)`
 *  - `next/font/google` import — 빌드 시 외부에서 폰트를 받는다
 *  - next.config 의 `images.remotePatterns`
 *  - 런타임 대입: `el.src = "https://..."`
 */

const EXTERNAL = /https?:\/\/[^\s"'`)]+/g
const CSS_URL = /url\(\s*['"]?(https?:\/\/[^\s'")]+)/gi

/**
 * 자산을 서빙하는 것 말고는 쓰임이 없는 호스트.
 *
 * 위치 기반 판정(아래 RESOURCE_ATTRIBUTES 등)은 "적재하는 자리"만 보므로
 * `const fontUrl = "https://fonts.googleapis.com/..."` 처럼 한 단계 건너 쓰는
 * 코드를 놓친다. 그런데 이 호스트들은 **존재 이유가 자산 전달**이라, 코드에
 * 글자로 등장한 시점에 이미 self-host 원칙을 벗어났다고 봐도 오탐이 아니다.
 * 위치와 무관하게 잡는 이유다.
 */
const ASSET_HOSTS = [
  "fonts.googleapis.com",
  "fonts.gstatic.com",
  "cdn.jsdelivr.net",
  "unpkg.com",
  "cdnjs.cloudflare.com",
  "use.typekit.net",
  "use.fontawesome.com",
]

const DEFAULT_ALLOW = [
  "http://localhost",
  "https://localhost",
  "http://127.0.0.1",
  "https://127.0.0.1",
  "http://0.0.0.0",
  "http://www.w3.org/",
  "https://www.w3.org/",
]

/** 브라우저가 받으러 가는 JSX 속성. */
const RESOURCE_ATTRIBUTES = new Set(["src", "srcSet", "srcset", "poster", "data"])

/** 런타임에 외부로 나가는 호출·생성자. */
const REQUEST_CALLEES = new Set(["fetch", "importScripts", "axios"])
const REQUEST_CONSTRUCTORS = new Set(["Worker", "SharedWorker", "WebSocket", "EventSource", "URL", "Request"])

/** 이 노드가 담은 문자열들(리터럴·템플릿 조각). */
function stringsOf(node) {
  if (!node) return []
  if (node.type === "Literal" && typeof node.value === "string") return [node.value]
  if (node.type === "TemplateLiteral") return node.quasis.map((q) => q.value.cooked ?? q.value.raw)
  if (node.type === "JSXExpressionContainer") return stringsOf(node.expression)
  return []
}

/** @type {import("eslint").Rule.RuleModule} */
export default {
  meta: {
    type: "problem",
    docs: {
      description: RULE_META["no-external-url"].summary,
      section: RULE_META["no-external-url"].section,
      url: "https://ui.doksam.com/rules/lint",
    },
    schema: [
      {
        type: "object",
        properties: {
          // 추가로 허용할 URL 접두. 폐쇄망 안에 실재하는 사내 호스트에만 쓴다.
          allow: { type: "array", items: { type: "string" } },
        },
        additionalProperties: false,
      },
    ],
    messages: {
      externalResource:
        "외부 리소스 '{{value}}' 를 불러온다 — 폰트·아이콘·이미지·스크립트는 전부 self-host 한다(next/font/local, npm 아이콘 패키지, public/ 로컬 이미지). doksam-ui 규칙 [invariant] '폐쇄망 대응' (https://ui.doksam.com/rules)",
      googleFont:
        "next/font/google 은 빌드 시 외부에서 폰트를 받는다 — next/font/local 을 쓰고 woff2 를 assets/fonts/ 에 커밋한다(라이선스 파일도 함께). doksam-ui 규칙 [invariant] '폐쇄망 대응' (https://ui.doksam.com/rules)",
      remotePatterns:
        "next.config 의 images.remotePatterns 에 외부 도메인을 등록하지 않는다 — next/image 는 로컬·자체 호스팅 이미지만 최적화 대상으로 둔다. doksam-ui 규칙 [invariant] '폐쇄망 대응' (https://ui.doksam.com/rules)",
    },
  },

  create(context) {
    const allow = [...DEFAULT_ALLOW, ...(context.options[0]?.allow ?? [])]
    const isAllowed = (url) => allow.some((prefix) => url.startsWith(prefix))
    const isAssetHost = (url) => ASSET_HOSTS.some((host) => url.includes(host))

    /** 리소스 적재 위치의 값 노드를 검사한다. */
    const checkResource = (node, valueNode) => {
      for (const text of stringsOf(valueNode)) {
        for (const match of text.matchAll(EXTERNAL)) {
          if (isAllowed(match[0])) continue
          context.report({ node, messageId: "externalResource", data: { value: match[0] } })
        }
      }
    }

    return {
      // 어느 위치든 CSS url() 은 곧 적재고, 자산 전용 호스트는 등장 자체가 위반이다.
      Literal(node) {
        if (typeof node.value !== "string") return
        for (const match of node.value.matchAll(CSS_URL)) {
          if (isAllowed(match[1])) continue
          context.report({ node, messageId: "externalResource", data: { value: match[1] } })
          return
        }
        for (const match of node.value.matchAll(EXTERNAL)) {
          if (isAllowed(match[0]) || !isAssetHost(match[0])) continue
          context.report({ node, messageId: "externalResource", data: { value: match[0] } })
        }
      },

      JSXAttribute(node) {
        const name = node.name?.name
        if (typeof name !== "string") return
        const isResourceAttr = RESOURCE_ATTRIBUTES.has(name)
        // href 는 <link> 만 적재다 — <a href>·<Link href> 는 사용자가 누르는 이동이다.
        const element = node.parent?.name?.name
        const isLinkHref = name === "href" && element === "link"
        if (!isResourceAttr && !isLinkHref) return
        checkResource(node, node.value)
      },

      CallExpression(node) {
        const callee = node.callee
        const name =
          callee.type === "Identifier"
            ? callee.name
            : callee.type === "MemberExpression" && callee.object?.type === "Identifier"
              ? callee.object.name
              : undefined
        if (!name || !REQUEST_CALLEES.has(name)) return
        for (const argument of node.arguments) checkResource(node, argument)
      },

      NewExpression(node) {
        if (node.callee?.type !== "Identifier" || !REQUEST_CONSTRUCTORS.has(node.callee.name)) return
        for (const argument of node.arguments) checkResource(node, argument)
      },

      AssignmentExpression(node) {
        if (node.left?.type !== "MemberExpression") return
        const property = node.left.property?.name ?? node.left.property?.value
        if (property !== "src" && property !== "href") return
        checkResource(node, node.right)
      },

      ImportDeclaration(node) {
        if (node.source?.value !== "next/font/google") return
        context.report({ node, messageId: "googleFont" })
      },

      Property(node) {
        const key = node.key?.name ?? node.key?.value
        if (key !== "remotePatterns") return
        // 빈 배열은 "외부 도메인 없음" 을 명시한 것이므로 통과시킨다.
        if (node.value?.type === "ArrayExpression" && node.value.elements.length === 0) return
        context.report({ node, messageId: "remotePatterns" })
      },
    }
  },
}

import { RULE_META } from "../meta.mjs"

/**
 * 하드코딩 색을 막는다 — 규칙 원문 "컬러 · 토큰" 절의 1번 조항.
 *
 * 세 갈래를 본다.
 *  1. 색 함수 리터럴: rgb()/rgba()/hsl()/oklch()/lab()/color-mix() 등
 *  2. hex 리터럴: #rrggbb·#rrggbbaa 는 항상, #rgb·#rgba 는 색 문맥에서만
 *     (`href="#abc"` 같은 앵커가 3자리 hex 와 구분되지 않기 때문이다 — 문맥을
 *     보지 않고 잡으면 오탐이 나고, 오탐이 나면 사람은 규칙 전체를 끈다)
 *  3. Tailwind 팔레트 클래스: text-red-500, bg-slate-200/50, border-t-blue-600,
 *     dark:hover:bg-white 처럼 변형 접두가 붙은 형태까지
 *
 * `bg-[#0f172a]` 같은 임의 값 클래스는 2번이 문자열 안에서 그대로 잡는다.
 */

/** Tailwind 기본 팔레트 — 시맨틱 토큰이 아닌 고정 색 이름. */
const PALETTE = [
  "slate",
  "gray",
  "zinc",
  "neutral",
  "stone",
  "red",
  "orange",
  "amber",
  "yellow",
  "lime",
  "green",
  "emerald",
  "teal",
  "cyan",
  "sky",
  "blue",
  "indigo",
  "violet",
  "purple",
  "fuchsia",
  "pink",
  "rose",
]

/** 색을 받는 유틸리티 접두 — 이 접두 + 팔레트 조합만 클래스로 본다. */
const COLOR_UTILITIES = [
  "bg",
  "text",
  "border",
  "ring",
  "outline",
  "fill",
  "stroke",
  "from",
  "via",
  "to",
  "shadow",
  "decoration",
  "divide",
  "accent",
  "caret",
  "placeholder",
  "selection",
]

const SHADES = "50|100|200|300|400|500|600|700|800|900|950"
const AXIS = "t|r|b|l|x|y|s|e|offset"
const OPACITY = "(?:\\/\\d{1,3})?"

const PALETTE_CLASS = new RegExp(
  `^(?:${COLOR_UTILITIES.join("|")})(?:-(?:${AXIS}))?-(?:(?:${PALETTE.join("|")})-(?:${SHADES})|white|black)${OPACITY}$`,
)

/** 색 함수 호출 — CSS 문자열 안에서 그대로 잡는다. */
const COLOR_FUNCTION = /\b(rgb|rgba|hsl|hsla|hwb|lab|lch|oklab|oklch|color-mix)\s*\(/

const HEX = /#[0-9a-fA-F]{3,8}\b/g

/**
 * 색 함수 인자에 들어간 CSS named color — hex 와 같은 하드코딩 색이다.
 *
 * `color-mix(in oklch, var(--chart-1) 20%, white)` 는 겉으로는 토큰 파생처럼
 * 보이지만 `white` 가 곧 `#ffffff` 다(#79 에서 카탈로그 자신이 실제로 이렇게
 * 우회했다). 문자열 전체가 아니라 **색 함수 인자 안에서만** 본다 — 밖에서도
 * 잡으면 "white paper" 같은 평범한 문장이 걸려 오탐이 쏟아진다.
 *
 * `transparent`·`currentColor` 는 색을 새로 만드는 것이 아니라 투명도·상속을
 * 가리키는 키워드라 제외한다.
 */
const NAMED_COLOR =
  /\b(?:white|black|red|green|blue|yellow|orange|purple|pink|brown|gray|grey|cyan|magenta|silver|gold|navy|teal|olive|maroon|lime|aqua|fuchsia|indigo|violet|beige|ivory|khaki|salmon|coral|crimson|turquoise|lavender|tan|plum|orchid|wheat|azure|snow|linen|tomato|chocolate|skyblue|steelblue|slateblue|midnightblue|whitesmoke|ghostwhite|antiquewhite|floralwhite|navajowhite|rebeccapurple)\b/i

/** 색 문맥으로 보는 식별자 — 속성 이름·객체 키·변수 이름에 쓰인다. */
const COLOR_NAME = /colou?r|fill|stroke|background|shadow|border|stop|palette|swatch|gradient|tint|shade/i

/** 변형 접두(`dark:`, `hover:`, `data-[x]:`)를 떼고 유틸리티 본문만 남긴다. */
function utilityOf(token) {
  let depth = 0
  let lastColon = -1
  for (let i = 0; i < token.length; i += 1) {
    const ch = token[i]
    if (ch === "[" || ch === "(") depth += 1
    else if (ch === "]" || ch === ")") depth -= 1
    else if (ch === ":" && depth === 0) lastColon = i
  }
  let utility = token.slice(lastColon + 1)
  // Tailwind v4 의 important 접미/접두와 음수 부호를 떼어 낸다.
  if (utility.startsWith("!")) utility = utility.slice(1)
  if (utility.endsWith("!")) utility = utility.slice(0, -1)
  if (utility.startsWith("-")) utility = utility.slice(1)
  return utility
}

/** 이 문자열이 색을 다루는 자리인가 — 3·4자리 hex 판정에만 쓴다. */
function inColorContext(node) {
  let current = node
  for (let depth = 0; current && depth < 4; depth += 1) {
    const parent = current.parent
    if (!parent) return false
    if (parent.type === "JSXAttribute" && parent.name?.name && COLOR_NAME.test(String(parent.name.name))) return true
    if (parent.type === "Property") {
      const key = parent.key?.name ?? parent.key?.value
      if (key && COLOR_NAME.test(String(key))) return true
    }
    if (parent.type === "VariableDeclarator" && parent.id?.name && COLOR_NAME.test(parent.id.name)) return true
    current = parent
  }
  return false
}

/**
 * 색 함수 호출 하나를 떼어내 "토큰에서 파생된 것인지" 판정한다.
 *
 * `start` 에서 시작하는 괄호를 짝 맞춰 닫는 데까지 잘라낸 뒤, 그 안에 `var(--…)`
 * 가 있고 색 리터럴(hex·중첩 색 함수)이 없으면 파생으로 본다.
 */
function isTokenDerived(text, start) {
  const open = text.indexOf("(", start)
  if (open === -1) return false
  let depth = 0
  let end = -1
  for (let i = open; i < text.length; i++) {
    if (text[i] === "(") depth++
    else if (text[i] === ")") {
      depth--
      if (depth === 0) {
        end = i
        break
      }
    }
  }
  const args = text.slice(open + 1, end === -1 ? text.length : end)
  // 인자에 숫자가 하나도 없으면 구체적인 색일 수 없다 — 템플릿 보간으로 값을
  // 채우는 `rgb(${r}, ${g}, ${b})` 같은 코드다(문자열 조각만 모으면 인자가
  // ", , " 로 남는다). 런타임 계산 결과를 문자열로 조립하는 것이지 색을 박은
  // 것이 아니므로 잡지 않는다.
  if (!/\d/.test(args)) return true
  if (!/var\(\s*--/.test(args)) return false
  // HEX 는 /g 라 test() 가 lastIndex 를 남긴다 — 상태 없는 match 로 확인한다.
  if (args.match(HEX)) return false
  // named color 가 섞이면 토큰 파생이 아니라 리터럴과의 혼합이다.
  if (NAMED_COLOR.test(args)) return false
  // 중첩 색 함수의 인자도 같은 기준으로 본다 — 안쪽이 리터럴이면 파생이 아니다.
  const inner = COLOR_FUNCTION.exec(args)
  if (inner && !isTokenDerived(args, inner.index)) return false
  return true
}

/** 문자열 하나에서 위반 조각을 모은다. */
function findViolations(text, node) {
  const found = []

  const fn = COLOR_FUNCTION.exec(text)
  // 색 함수라도 인자가 토큰(var(--x))뿐이면 값을 새로 만든 것이 아니라 토큰을
  // 가공한 것이다 — color-mix(in oklch, var(--foreground) 8%, transparent) 는
  // 그림자 농도를 토큰에서 파생시키는 정상 용법이라 잡지 않는다. 안에 색
  // 리터럴이 섞여 있으면(#fff·oklch(0.5 0 0) 등) 그때는 하드코딩이다.
  if (fn && !isTokenDerived(text, fn.index)) found.push(`${fn[1]}()`)

  for (const match of text.matchAll(HEX)) {
    const digits = match[0].length - 1
    if (digits === 6 || digits === 8) found.push(match[0])
    else if ((digits === 3 || digits === 4) && inColorContext(node)) found.push(match[0])
  }

  for (const token of text.split(/\s+/)) {
    if (!token) continue
    if (PALETTE_CLASS.test(utilityOf(token))) found.push(token)
  }

  return found
}

/** @type {import("eslint").Rule.RuleModule} */
export default {
  meta: {
    type: "problem",
    docs: {
      description: RULE_META["no-hardcoded-color"].summary,
      section: RULE_META["no-hardcoded-color"].section,
      url: "https://ui.doksam.com/rules/lint",
    },
    schema: [
      {
        type: "object",
        properties: {
          // 색 자체가 데이터인 자리(색 선택기 스와치 등)를 위한 탈출구.
          allow: { type: "array", items: { type: "string" } },
        },
        additionalProperties: false,
      },
    ],
    messages: {
      hardcodedColor:
        "하드코딩 색 '{{value}}' — 시맨틱 토큰(bg-background, text-destructive, text-chart-1)만 쓴다. doksam-ui 규칙 [invariant] '컬러 · 토큰' (https://ui.doksam.com/rules)",
    },
  },

  create(context) {
    const allow = new Set(context.options[0]?.allow ?? [])

    const check = (node, text) => {
      if (typeof text !== "string" || text.length === 0) return
      for (const value of findViolations(text, node)) {
        if (allow.has(value)) continue
        context.report({ node, messageId: "hardcodedColor", data: { value } })
      }
    }

    return {
      Literal(node) {
        if (typeof node.value === "string") check(node, node.value)
      },
      TemplateElement(node) {
        check(node, node.value.cooked ?? node.value.raw)
      },

      /**
       * 템플릿 리터럴은 조각(quasi)별로 검사하면 색 함수가 조각 경계에서 쪼개져
       * 빠져나간다 — `` `color-mix(in oklch, ${c} 20%, white)` `` 는 앞 조각에
       * 숫자가 없어 "보간으로 값을 채우는 코드" 로 통과하고, 뒤 조각에는 색
       * 함수가 없어 아무도 `white` 를 보지 않는다(#79).
       *
       * 그래서 보간 자리를 토큰 참조로 메운 **합친 문자열**을 한 번 더 본다.
       * 보간의 실제 값은 정적으로 알 수 없으므로 토큰으로 가정하고, 글자로 적힌
       * 리터럴만 판정한다.
       */
      TemplateLiteral(node) {
        if (node.expressions.length === 0) return
        const joined = node.quasis
          .map((q) => q.value.cooked ?? q.value.raw)
          .join("var(--interpolated)")
        const fn = COLOR_FUNCTION.exec(joined)
        if (!fn || isTokenDerived(joined, fn.index)) return
        context.report({ node, messageId: "hardcodedColor", data: { value: `${fn[1]}()` } })
      },
    }
  },
}

import { RULE_META } from "../meta.mjs"

/**
 * components/ui/ 안에 하위 폴더를 만들어 커스텀을 끼워 넣는 것을 막는다 —
 * 규칙 원문 "컴포넌트" 절의 4번 조항.
 *
 * components/ui/ 는 shadcn CLI 가 설치한 상류 원본이 놓이는 평평한 디렉터리다.
 * 그 안에 components/ui/customs/ 같은 폴더가 생기면 "손대지 않는 영역" 의 경계가
 * 흐려지고, 상류 재설치·드리프트 대조가 하우스 코드까지 훑게 된다.
 *
 * 절의 다른 조항("components/ui/ 를 손으로 고치지 않는다")의 전면 판정은 상류
 * 원문과의 대조가 필요해 폐쇄망 소비 프로젝트에서는 할 수 없다 — 카탈로그의
 * `pnpm check:shadcn` 이 맡는다. 여기서는 정적으로 확정되는 것만 본다.
 */

/** `.../components/ui/<sub>/<file>` 인가. src/ 레이아웃도 같이 본다. */
function nestedSegment(filename) {
  const normalized = filename.replaceAll("\\", "/")
  const marker = "/components/ui/"
  const at = normalized.lastIndexOf(marker)
  if (at === -1) return null
  const rest = normalized.slice(at + marker.length)
  const slash = rest.indexOf("/")
  return slash === -1 ? null : rest.slice(0, slash)
}

/** @type {import("eslint").Rule.RuleModule} */
export default {
  meta: {
    type: "problem",
    docs: {
      description: RULE_META["no-nested-ui-dir"].summary,
      section: RULE_META["no-nested-ui-dir"].section,
      url: "https://ui.doksam.com/rules/lint",
    },
    schema: [],
    messages: {
      nestedUiDir:
        "components/ui/{{segment}}/ — components/ui/ 안에 하위 폴더를 만들지 않는다. 커스텀은 components/ 또는 components/patterns/ 에서 프리미티브를 조합한다. doksam-ui 규칙 [invariant] '컴포넌트' (https://ui.doksam.com/rules)",
    },
  },

  create(context) {
    return {
      Program(node) {
        const segment = nestedSegment(context.filename ?? context.getFilename())
        if (!segment) return
        context.report({ node, messageId: "nestedUiDir", data: { segment } })
      },
    }
  },
}

import fs from "node:fs"
import path from "node:path"

import { RULE_META } from "../meta.mjs"

/**
 * 새 라우트에 loading·error 경계가 없으면 보고한다 — 규칙 원문 "페이지 · 라우팅" 절.
 *
 * Next App Router 에서 `loading.tsx`·`error.tsx` 는 그 세그먼트와 **하위 전체**에
 * 적용된다. 그래서 "같은 폴더에 있는가" 로 판정하면 중첩 라우트마다 오탐이 난다 —
 * 상위 세그먼트를 `app/` 까지 거슬러 올라가며 본다. 이 판정 범위가 Next 의 실제
 * 적용 범위와 같다.
 *
 * 파일시스템을 직접 보는 규칙이라 RuleTester 도 실재하는 픽스처 경로로 돌린다.
 */

const PAGE_FILES = new Set(["page.tsx", "page.jsx", "page.ts", "page.js", "page.mdx"])
const EXTENSIONS = [".tsx", ".jsx", ".ts", ".js", ".mdx"]

/** 세그먼트 디렉터리에 그 규약 파일이 있는가. */
function hasConvention(dir, base) {
  return EXTENSIONS.some((ext) => fs.existsSync(path.join(dir, base + ext)))
}

/**
 * page 파일에서 `app/` 루트까지 올라가며 규약 파일을 찾는다.
 * app 디렉터리 밖이면 App Router 가 아니라고 보고 판정하지 않는다.
 */
function missingBoundaries(pageFile) {
  let dir = path.dirname(pageFile)
  const missing = new Set(["loading", "error"])
  for (;;) {
    for (const base of [...missing]) {
      if (hasConvention(dir, base)) missing.delete(base)
    }
    if (path.basename(dir) === "app") return [...missing]
    const parent = path.dirname(dir)
    if (parent === dir) return null // app/ 를 못 찾았다 — App Router 가 아니다.
    dir = parent
  }
}

/** @type {import("eslint").Rule.RuleModule} */
export default {
  meta: {
    type: "problem",
    docs: {
      description: RULE_META["require-route-boundaries"].summary,
      section: RULE_META["require-route-boundaries"].section,
      url: "https://ui.doksam.com/rules/lint",
    },
    schema: [],
    messages: {
      missingBoundary:
        "이 라우트에 {{missing}} 경계가 없다 — 새 라우트를 추가하면 loading.tsx 와 error.tsx 를 함께 만든다(상태 UI 는 ui.doksam.com/patterns/state). doksam-ui 규칙 [invariant] '페이지 · 라우팅' (https://ui.doksam.com/rules)",
    },
  },

  create(context) {
    return {
      Program(node) {
        const filename = context.filename ?? context.getFilename()
        if (!path.isAbsolute(filename)) return
        if (!PAGE_FILES.has(path.basename(filename))) return

        const missing = missingBoundaries(filename)
        if (!missing || missing.length === 0) return

        context.report({
          node,
          messageId: "missingBoundary",
          data: { missing: missing.map((base) => `${base}.tsx`).join(" · ") },
        })
      },
    }
  },
}
